"""Port risc0's generated rv32im accumulate step (CUDA) to Metal: kernels/rv32im_accum.metal.

Takes `step_TopAccum` and every function it reaches from risc0-circuit-rv32im-sys 4.0.2's
kernels/cuda/steps.cu (29 functions, ~44k lines; its only extern is a no-op assert), with the value
and layout types and the layout constants, and rewrites the CUDA-isms for Metal (address spaces,
`metal::array`). The helpers it relies on are in kernels/accum.h.

Usage: port_accum.py [SYS_CRATE_DIR]   (default: the crate in ~/.cargo/registry)
"""
import glob
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
if len(sys.argv) > 1:
    SYS = Path(sys.argv[1])
else:
    SYS = Path(sorted(glob.glob(str(Path.home() / ".cargo/registry/src/*/risc0-circuit-rv32im-sys-4.0.2")))[-1])
CUDA = SYS / "kernels" / "cuda"


def metal(text):
    text = text.replace("::cuda::std::array", "cuarray")
    text = re.sub(r"\bextern __device__\s+", "", text)
    text = re.sub(r"\b__device__\s+", "", text)
    text = re.sub(r"\bExecContext&\s*ctx", "thread ExecContext& ctx", text)
    text = re.sub(r"\bconst char\*", "constant char*", text)
    return text


steps = (CUDA / "steps.cu").read_text()
defs = {}
for m in re.finditer(r"__device__\s+[\w:<>,\s]*?\b(\w+)\s*\(", steps):
    if m.group(1) not in ("if", "for", "while", "return"):
        defs.setdefault(m.group(1), m.start())
starts = sorted(set(defs.values()))
end_of_namespace = steps.rindex("} // namespace")
bounds = {}
for name, start in defs.items():
    i = starts.index(start)
    bounds[name] = (start, starts[i + 1] if i + 1 < len(starts) else end_of_namespace)
todo, seen = ["step_TopAccum"], set()
while todo:
    name = todo.pop()
    if name in seen or name not in bounds:
        continue
    seen.add(name)
    start, end = bounds[name]
    todo.extend(c for c in set(re.findall(r"\b(\w+)\(", steps[start:end])) if c != name and c in bounds)

# Prototypes for the functions we keep, then their definitions in file order.
header = (CUDA / "steps.cuh").read_text()
protos = []
for m in re.finditer(r"extern __device__ [^;]*?\b(\w+)\([^;]*\);", header):
    if m.group(1) in seen:
        protos.append(metal(m.group(0)))
bodies = [metal(steps[bounds[n][0]:bounds[n][1]]).rstrip() for n in sorted(seen, key=lambda n: bounds[n][0])]

defs_inc = re.sub(r"\bconstexpr size_t\b", "constant size_t", (CUDA / "defs.cu.inc").read_text())
types_inc = metal((CUDA / "types.cuh.inc").read_text())
layouts = re.sub(r"\b__device__ constexpr\b", "constant", (CUDA / "layout.cu.inc").read_text())
layouts = metal(layouts)

kernel = """
// One thread per cycle: phase 1 of risc0_circuit_rv32im_cpu_accum (kernels/cxx/ffi.cpp). Phases
// 2 and 3 (prefix sums over the last 4 columns, then adding them in) run on the CPU.
constant size_t kUserAccumSplit = 23;

kernel void rv32im_step_accum(device Fp* data [[buffer(0)]],
                              device Fp* accum [[buffer(1)]],
                              device Fp* global [[buffer(2)]],
                              device Fp* mix [[buffer(3)]],
                              constant uint2& cfg [[buffer(4)]],
                              uint cycle [[thread_position_in_grid]]) {
  if (cycle >= cfg.y) {
    return;
  }
  ExecContext ctx{cycle};
  BufferObj dataBuf{data, cfg.x, 0, false};
  BufferObj accumBuf{accum, cfg.x, kUserAccumSplit, false};
  BufferObj globalBuf{global, 1, 0, true};
  BufferObj mixBuf{mix, 1, 0, true};
  step_TopAccum(ctx, &accumBuf, &dataBuf, &globalBuf, &mixBuf);
}
"""

out = ["// Generated by tools/port_accum.py from risc0-circuit-rv32im-sys 4.0.2 (Apache-2.0).",
       '#include "accum.h"', defs_inc, types_inc, layouts, *protos, *bodies, kernel]
(ROOT / "kernels" / "rv32im_accum.metal").write_text("\n".join(out) + "\n")
print(f"{len(seen)} functions, {sum(b.count(chr(10)) for b in bodies)} lines -> kernels/rv32im_accum.metal")
